import math
from collections.abc import Iterable, Mapping
from typing import cast

from log_events import normalize_event


def latency_quantile(
    events: Iterable[Mapping[str, object]], q: int | float,
) -> float | None:
    if type(q) not in (int, float):
        raise ValueError("quantile must be finite and in [0, 1]")
    try:
        quantile = float(q)
    except (OverflowError, ValueError):
        raise ValueError("quantile must be finite and in [0, 1]") from None
    if not math.isfinite(quantile) or not 0 <= quantile <= 1:
        raise ValueError("quantile must be finite and in [0, 1]")

    values = sorted(cast(float, normalize_event(row)["latency_ms"]) for row in events)
    if not values:
        return None
    position = quantile * (len(values) - 1)
    lower = math.floor(position)
    upper = math.ceil(position)
    fraction = position - lower
    return values[lower] + fraction * (values[upper] - values[lower])

