import json

from log_events import normalize_event


def parse_jsonl(text: str) -> list[dict[str, int | float | str]]:
    if not isinstance(text, str):
        raise ValueError("JSONL input must be text")

    events: list[dict[str, int | float | str]] = []
    for line_number, line in enumerate(text.splitlines(), 1):
        if not line.strip():
            continue
        try:
            raw = json.loads(line)
        except json.JSONDecodeError:
            raise ValueError(f"line {line_number} is invalid JSON") from None
        if not isinstance(raw, dict):
            raise ValueError(f"line {line_number}: event must be an object")
        try:
            events.append(normalize_event(raw))
        except ValueError as error:
            raise ValueError(f"line {line_number}: {error}") from None
    return events

