from collections.abc import Iterable, Mapping
from typing import cast

from log_events import normalize_event


def count_statuses(events: Iterable[Mapping[str, object]]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for row in events:
        status = cast(str, normalize_event(row)["status"])
        counts[status] = counts.get(status, 0) + 1
    return {status: counts[status] for status in sorted(counts)}
